mapper.update:
update es_team
set name = #{name}, short_name = #{shortName}, region = #{region},
    world_rank = #{worldRank}, color1 = #{color1}, color2 = #{color2}
where id = #{id}

update es_tournament
set name = #{name},
    region = #{region},
    start_date = #{startDate,jdbcType=VARCHAR},
    end_date = #{endDate,jdbcType=VARCHAR}
where id = #{id}
